<script setup>
import {computed, ref, watch, onMounted, onBeforeUnmount} from 'vue'
import axios from 'axios'
import PdfResultPreview from './PdfResultPreview.vue'
const groups=[{name:'页面整理',tools:[['merge','合并 PDF','按左侧文件顺序合并全部页面。'],['extract','提取 / 重排','填写页码顺序，提取或重新排列页面。'],['split','逐页拆分','将指定页面分别保存为 PDF，打包下载。'],['delete','删除页面','删除填写的页面，保留其他页面。'],['rotate','旋转页面','仅旋转指定页面，保持其余页面不变。'],['compress','无损压缩','优化重复对象和内容流，保留原始图片质量；体积可能不会减小。'],['watermark','文字水印','为指定页面添加居中斜向文字水印。']]},{name:'格式转换',tools:[['pdf-to-word','PDF → Word','由服务器解析文字层、表格和版面，生成可编辑 DOCX。'],['word-to-pdf','Word → PDF','通过服务器 LibreOffice 转换 DOC / DOCX。'],['images-to-pdf','图片 → PDF','按文件顺序将图片合成为 A4 PDF。'],['pdf-to-images','PDF → 图片','将每页渲染为 PNG，打包下载。']]},{name:'文字提取',tools:[['text','提取文本','提取已有文字层，不调用模型。'],['ocr','多模态 OCR','将所选页面图片发送至已配置的多模态模型，提取扫描件文字。']]}]
const resultExpanded=ref(false), previewResult=ref(false), resultQuery=ref(''), mainResult=ref(false)
const operation=ref('merge'), files=ref([]), currentId=ref(''), input=ref(), busy=ref(false), error=ref(''), result=ref(null), progress=ref(0), phase=ref(''), dragging=ref(false), capabilities=ref(null)
const pages=ref(''), angle=ref(90), watermark=ref('内部资料'), ocrFormat=ref('md')
watch([currentId,operation],()=>{mainResult.value=false})
const history=ref([]), historyLoading=ref(false), historyError=ref(''), confirmDelete=ref(false)
let selectionSequence=0
async function loadHistory(){try{history.value=(await axios.get('/api/pdf-toolbox/results')).data;historyError.value=''}catch{historyError.value='处理记录加载失败，请重试。'}}
async function selectResult(item){const seq=++selectionSequence;historyLoading.value=true;historyError.value='';try{const {data}=await axios.get(`/api/pdf-toolbox/results/${item.id}/download`,{responseType:'blob'});const text=['txt','md'].includes(item.ext)?await data.text():'';if(seq!==selectionSequence)return;clearResult();result.value={...item,blob:data,url:URL.createObjectURL(data),text,title:groups.flatMap(g=>g.tools).find(t=>t[0]===item.operation)?.[1]||item.operation,createdAt:new Date(item.createdAt).toLocaleString()};mainResult.value=item.ext==='pdf';resultExpanded.value=true}catch{if(seq===selectionSequence)historyError.value='结果文件加载失败，请重试。'}finally{if(seq===selectionSequence)historyLoading.value=false}}
function requestRemoveResult(){if(result.value)confirmDelete.value=true}
function cancelRemoveResult(){confirmDelete.value=false}
async function removeStoredResult(){confirmDelete.value=false;try{await axios.delete(`/api/pdf-toolbox/results/${result.value.id}`);clearResult();await loadHistory()}catch{historyError.value='移除失败，请重试。'}}
let controller
const tool=computed(()=>groups.flatMap(g=>g.tools).find(t=>t[0]===operation.value))
const current=computed(()=>files.value.find(f=>f.id===currentId.value)||files.value[0])
const multi=computed(()=>['merge','images-to-pdf'].includes(operation.value))
const accept=computed(()=>operation.value==='word-to-pdf'?'.doc,.docx':operation.value==='images-to-pdf'?'.png,.jpg,.jpeg,.webp':'.pdf')
const eligible=f=>accept.value.split(',').some(ext=>f.name.toLowerCase().endsWith(ext))
const inputs=computed(()=>multi.value?files.value.filter(eligible):current.value&&eligible(current.value)?[current.value]:[])
const pageOption=computed(()=>!['merge','images-to-pdf','word-to-pdf'].includes(operation.value))
const canRun=computed(()=>inputs.value.length&&!busy.value&&!(operation.value==='ocr'&&capabilities.value&&!capabilities.value.ocr_configured)&&!(operation.value==='word-to-pdf'&&capabilities.value&&!capabilities.value.word_to_pdf))
function switchTool(id){if(busy.value)return;operation.value=id;error.value='';if(current.value&&!eligible(current.value))currentId.value=files.value.find(eligible)?.id||currentId.value}
function add(list){if(busy.value)return;error.value='';for(const file of list){if(!/\.(pdf|docx?|png|jpe?g|webp)$/i.test(file.name)){error.value='支持 PDF、Word 和 PNG/JPG/WebP 图片';continue}if(files.value.length>=30||files.value.reduce((n,f)=>n+f.file.size,0)+file.size>100*1024*1024){error.value='最多 30 个文件，总大小不超过 100 MB';break}const id=crypto.randomUUID();files.value.push({id,file,name:file.name,url:URL.createObjectURL(file)});currentId.value=id}}
function choose(e){add([...e.target.files]);e.target.value=''}
function drop(e){dragging.value=false;add([...e.dataTransfer.files])}
function remove(id){const i=files.value.findIndex(f=>f.id===id);URL.revokeObjectURL(files.value[i].url);files.value.splice(i,1);if(currentId.value===id)currentId.value=files.value[Math.min(i,files.value.length-1)]?.id||''}
function move(i,delta){const j=i+delta;if(j<0||j>=files.value.length)return;[files.value[i],files.value[j]]=[files.value[j],files.value[i]]}
function clearResult(){if(result.value)URL.revokeObjectURL(result.value.url);result.value=null;mainResult.value=false;resultExpanded.value=false;previewResult.value=false;resultQuery.value=''}
async function run(){if(!canRun.value)return;busy.value=true;error.value='';progress.value=1;phase.value='上传文件';controller=new AbortController();const op=operation.value;const taskId=crypto.randomUUID();const signal=controller.signal;let polling=true;let pollTimer
const poll=async()=>{try{const {data}=await axios.get(`/api/pdf-toolbox/progress/${taskId}`,{signal});if(polling&&data.progress>=progress.value){progress.value=data.progress;phase.value=data.phase}}catch{}finally{if(polling)pollTimer=setTimeout(poll,500)}}
pollTimer=setTimeout(poll,300);try{const data=new FormData();inputs.value.forEach(f=>data.append('files',f.file,f.name));data.append('operation',op);data.append('task_id',taskId);data.append('options',JSON.stringify({pages:pages.value,angle:angle.value,watermark:watermark.value,ocr_format:ocrFormat.value}));const response=await axios.post('/api/pdf-toolbox/process',data,{responseType:'blob',signal:controller.signal,onUploadProgress:e=>{progress.value=Math.max(progress.value,Math.min(10,Math.round(e.loaded/(e.total||e.loaded)*10)));if(progress.value===10)phase.value='服务器处理中'}});const ext=op==='pdf-to-word'?'docx':op==='ocr'?ocrFormat.value:['split','pdf-to-images'].includes(op)?'zip':op==='text'?'txt':'pdf';const text=['txt','md'].includes(ext)?await response.data.text():'';clearResult();result.value={id:response.headers['x-result-id'],blob:response.data,url:URL.createObjectURL(response.data),name:`${inputs.value[0].name.replace(/\.[^.]+$/,'')}-${op}.${ext}`,size:response.data.size,ext,text,title:tool.value[1],createdAt:new Date().toLocaleString()};if(ext==='pdf')mainResult.value=true;if(op==='watermark')resultExpanded.value=true;progress.value=100;phase.value='处理完成';await loadHistory()}catch(e){if(e.code==='ERR_CANCELED')error.value='已停止等待；已提交的服务器处理可能仍会完成。';else{let detail;try{detail=JSON.parse(await e.response.data.text()).detail}catch{}error.value=detail||(e.response?.status===404?'后端尚未加载 PDF 工具箱，请重启后端服务。':'处理失败，请检查文件或服务器连接。')}}finally{polling=false;clearTimeout(pollTimer);busy.value=false;controller=null}}
const size=n=>n>1024*1024?(n/1024/1024).toFixed(1)+' MB':Math.ceil(n/1024)+' KB'
onMounted(async()=>{await loadHistory();if(history.value.length&&!result.value&&!busy.value)await selectResult(history.value[0]);try{capabilities.value=(await axios.get('/api/pdf-toolbox/capabilities')).data}catch{}})
onBeforeUnmount(()=>{selectionSequence++;controller?.abort();files.value.forEach(f=>URL.revokeObjectURL(f.url));clearResult()})
</script>
<template>
<section class="pdf-toolbox-page">
  <header><div><span class="eyebrow">PDF WORKSPACE</span><h1>PDF 工具箱</h1><p>导入文件，选择操作，预览并下载结果。</p></div><span class="pdf-badge">PDF · WORD · IMAGE · OCR</span></header>
  <div class="pdf-studio">
    <nav class="pdf-tools" aria-label="PDF 工具"><div v-for="group in groups" :key="group.name"><b>{{group.name}}</b><div><button v-for="item in group.tools" :key="item[0]" :class="{active:operation===item[0]}" :aria-pressed="operation===item[0]" :disabled="busy" @click="switchTool(item[0])">{{item[1]}}</button></div></div></nav>
    <div class="pdf-command"><div><b>{{tool[1]}}</b><span>{{tool[2]}}</span></div><span class="pdf-backend">服务器处理 · 完成后下载</span></div>
    <div class="pdf-layout">
      <aside class="pdf-files" @dragover.prevent="dragging=true" @dragleave="dragging=false" @drop.prevent="drop" :class="{dragging}">
        <div class="pdf-section-head"><b>01 · 导入文件</b><button :disabled="busy" @click="input.click()">＋ 添加</button><input ref="input" class="pdf-hidden-input" type="file" :accept="accept" multiple hidden @change="choose"></div>
        <p class="pdf-hint">{{multi?'按列表顺序处理匹配的文件':'点击选择要处理的文件'}} · 总计 {{files.length}} 个</p>
        <div v-if="!files.length" class="pdf-drop" @click="input.click()"><span>＋</span><b>拖入文件到这里</b><small>{{accept}} · 总大小 ≤ 100 MB</small></div>
        <div class="pdf-file-list"><article v-for="(file,i) in files" :key="file.id" :class="{selected:current?.id===file.id,muted:!eligible(file)}"><button class="pdf-file-name" :disabled="busy" @click="currentId=file.id"><span>{{String(i+1).padStart(2,'0')}}</span><div><b :title="file.name">{{file.name}}</b><small>{{size(file.file.size)}}{{!eligible(file)?' · 当前操作不适用':''}}</small></div></button><div class="pdf-file-actions"><button :disabled="busy||i===0" :aria-label="`上移 ${file.name}`" @click="move(i,-1)">↑</button><button :disabled="busy||i===files.length-1" :aria-label="`下移 ${file.name}`" @click="move(i,1)">↓</button><button :disabled="busy" :aria-label="`移除 ${file.name}`" @click="remove(file.id)">×</button></div></article></div>
        <section class="pdf-options"><b>02 · 操作设置</b><label v-if="pageOption">{{operation==='delete'?'删除页码':'页码 / 顺序'}}<input v-model="pages" :disabled="busy" placeholder="例如 1,3-5,2；留空为全部"></label><small v-if="pageOption">页码从 1 开始；支持区间和倒序。{{operation==='delete'?'删除时必须填写页码。':''}}</small><label v-if="operation==='rotate'">旋转角度<select v-model="angle" :disabled="busy"><option :value="90">顺时针 90°</option><option :value="180">180°</option><option :value="270">逆时针 90°</option></select></label><label v-if="operation==='watermark'">水印文字<input v-model="watermark" maxlength="80" :disabled="busy" placeholder="例如：内部资料"></label><p v-if="operation==='watermark'" class="pdf-hint">居中斜向、半透明红色水印，字号随页面适配。处理完成后右侧自动显示带水印结果，可切换原文件对照。</p><label v-if="operation==='ocr'">输出格式<select v-model="ocrFormat" :disabled="busy"><option value="md">Markdown 文本</option><option value="docx">Word 文档</option></select></label><p v-if="operation==='pdf-to-word'" class="pdf-hint">支持文字、表格和版面转换。扫描件需切换 OCR；复杂版式转换后请校对。</p><p v-if="operation==='ocr'" class="pdf-hint">每次最多 20 页。点击处理将把页面图片发送到现有模型服务。{{capabilities?.ocr_model?'当前模型：'+capabilities.ocr_model:'使用服务器现有多模态配置。'}}</p><p v-if="operation==='ocr'&&capabilities?.ocr_error" class="pdf-error">{{capabilities.ocr_error}}</p><p v-if="operation==='word-to-pdf'&&capabilities&&!capabilities.word_to_pdf" class="pdf-error">服务器未安装 LibreOffice，安装后可使用此功能。</p><button class="pdf-run" :disabled="!canRun" @click="run">{{busy?phase:inputs.length?`开始处理 · ${inputs.length} 个文件`:'先添加适用文件'}}</button><p v-if="error" class="pdf-error" role="alert">{{error}}</p></section>
      </aside>
      <section class="pdf-preview"><div class="pdf-section-head"><b>{{mainResult?'03 · 处理结果预览':'03 · 原文件预览'}}</b><div><small :title="mainResult?result?.name:current?.name">{{mainResult?result?.name:current?.name||'尚未选择文件'}}</small><button v-if="result?.ext==='pdf'" @click="mainResult=!mainResult">{{mainResult?'查看原文件':'查看处理结果'}}</button></div></div><PdfResultPreview v-if="mainResult&&result?.ext==='pdf'" :key="result.url" :blob="result.blob"/><iframe v-else-if="current?.name.toLowerCase().endsWith('.pdf')" :src="current.url" title="原 PDF 预览"></iframe><div v-else-if="current&&/\.(png|jpe?g|webp)$/i.test(current.name)" class="pdf-image-preview"><img :src="current.url" :alt="current.name"></div><div v-else class="pdf-empty"><span>PDF</span><b>{{current?'Word 文件已就绪':'文件与操作，一目了然'}}</b><p>{{current?'转换完成后可预览生成的 PDF。':'在左侧导入文件，然后选择上方工具。原文件保持不变。'}}</p></div></section>
    </div>
  </div>
  <section class="queue">
    <div class="queue-head"><div><span class="eyebrow">PDF TASK QUEUE</span><h2>处理结果</h2></div></div>
    <article v-if="busy" class="task" aria-busy="true"><div class="task-main"><div class="task-icon"><svg class="ai-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 2h8l4 4v16H6V2m8 0v5h5M9 13h6m-6 4h6" /></svg></div><div><b>{{tool[1]}}</b><small>{{inputs.length}} 个文件 · {{phase}}</small></div></div><div class="progress" role="status"><div><span>{{phase}}</span><strong>{{progress}}%</strong></div><div class="track" role="progressbar" :aria-valuenow="progress" aria-valuemin="0" aria-valuemax="100" :aria-label="phase"><i class="running" :style="{width:progress+'%'}"></i></div></div><span class="badge running">处理中</span><div class="task-actions pdf-task-actions"><button @click="controller?.abort()">停止等待</button></div></article>
    <p v-if="historyError" class="pdf-error" role="alert">{{historyError}} <button @click="loadHistory">重试</button></p>
    <div v-if="history.length" class="pdf-history" aria-label="已保存的处理结果"><button v-for="item in history" :key="item.id" :class="{active:result?.id===item.id}" :disabled="busy||historyLoading" @click="selectResult(item)"><b>{{item.name}}</b><small>{{new Date(item.createdAt).toLocaleString()}} · {{size(item.size)}}</small></button></div>
    <p v-if="historyLoading" role="status">正在加载已保存的结果…</p>
    <div v-if="!result&&!busy&&!historyLoading" class="empty">暂无处理结果。完成处理后，可在此查看和下载文件。</div>
    <article v-if="result" class="task">
      <div class="task-main"><div class="task-icon"><svg class="ai-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M6 2h8l4 4v16H6V2m8 0v5h5M9 13h6m-6 4h6" /></svg></div><div><b>{{result.title}}</b><small>{{result.createdAt}} · {{size(result.size)}}</small></div></div>
      <div class="progress"><div><span>文件处理完成</span><strong>100%</strong></div><div class="track"><i class="completed" style="width:100%"></i></div></div>
      <span class="badge completed">已完成</span>
      <div class="task-actions pdf-task-actions"><button class="pdf-result-btn" :aria-expanded="resultExpanded" @click="resultExpanded=!resultExpanded;if(!resultExpanded)previewResult=false">{{resultExpanded?'收起结果':'查看结果'}} <span>1</span></button><a :href="result.url" :download="result.name">下载 {{result.ext.toUpperCase()}}</a><button class="danger" :disabled="busy" @click="requestRemoveResult">移除结果</button></div>
      <div v-if="resultExpanded" class="pdf-inline-list"><div class="pdf-inline-head"><div><b>处理结果</b><small>{{result.name.toLowerCase().includes(resultQuery.toLowerCase())?1:0}} / 1 个文件</small></div><input v-model="resultQuery" type="search" placeholder="搜索文件名"></div><div class="pdf-inline-scroll"><div v-if="!result.name.toLowerCase().includes(resultQuery.toLowerCase())" class="pdf-inline-empty">没有匹配的文件</div><div v-else class="pdf-inline-row"><div><span>{{result.name}}</span><small>{{result.ext.toUpperCase()}} · {{size(result.size)}}</small></div><button v-if="result.ext==='pdf'||result.text" @click="previewResult=!previewResult">{{previewResult?'关闭预览':'预览'}}</button><a v-else :href="result.url" :download="result.name">下载</a></div></div>
      <div v-if="previewResult" class="pdf-toolbox-output"><div class="pdf-preview-head"><b>{{result.name}}</b></div><PdfResultPreview v-if="result.ext==='pdf'" :blob="result.blob"/><textarea v-else :value="result.text" readonly aria-label="提取结果"></textarea></div></div>
    </article>
  </section>
  <div v-if="confirmDelete" class="pdf-confirm-backdrop" role="presentation" @click.self="cancelRemoveResult">
    <section class="pdf-confirm" role="dialog" aria-modal="true" aria-labelledby="pdf-confirm-title">
      <b id="pdf-confirm-title">移除处理结果？</b>
      <p>将移除“{{result?.name}}”的历史记录和下载文件，此操作不可恢复。</p>
      <div><button @click="cancelRemoveResult">取消</button><button class="danger" @click="removeStoredResult">确认移除</button></div>
    </section>
  </div>
</section>
</template>
<style scoped>
.pdf-confirm-backdrop{position:fixed;inset:0;z-index:1000;display:grid;place-items:center;padding:20px;background:#10181666}.pdf-confirm{width:min(420px,100%);padding:22px;background:var(--ui-surface,#fffef9);color:var(--ui-text,var(--pop-ink));border:2px solid var(--pop-ink);box-shadow:5px 5px var(--pop-ink);border-radius:4px}.pdf-confirm>b{display:block;font-size:15px}.pdf-confirm p{margin:12px 0 20px;font-size:12px;line-height:1.7;color:var(--ui-text-muted,#68736d)}.pdf-confirm>div{display:flex;justify-content:flex-end;gap:10px}.pdf-confirm button{padding:8px 16px;border:1px solid var(--pop-line);border-radius:3px;background:var(--ui-surface,#fffef9);color:var(--ui-text,var(--pop-ink));cursor:pointer}.pdf-confirm button:hover{background:#dff7fa}.pdf-confirm button.danger{background:#ffe0e5;border-color:#a22f42;color:#8b2638;font-weight:700}.pdf-confirm button.danger:hover{background:#ffcbd3}

